class Wrapper<T> {
    private T value;
    public Wrapper(T value) { this.value = value; }
    public boolean equals(Object obj) {
        if (obj instanceof Wrapper) {
            return value.equals(((Wrapper) obj).value);
        }
        return false;
    }
}
public class Test {
    public static void main(String[] args) {
        Wrapper<String> w1 = new Wrapper<>("Test");
        Wrapper<String> w2 = new Wrapper<>("Test");
